{"implementation": "def solve(case):
    payload = case["payload"]
    text = payload["text"]
    passes = payload["passes"]
    max_rounds = payload["max_rounds"]
    for _ in range(max_rounds):
        changed = False
        for p in passes:
            old, new = p["old"], p["new"]
            new_text = text.replace(old, new)
            if new_text != text:
                changed = True
                text = new_text
        if not changed:
            break
    return text"}
